  /* ── D86 backprop ──────────────────────────────────────────────────── */
  'backprop-flow': {
    family: 'graph',
    title: 'Blame flows backwards — the same net, gradients running right to left',
    frames: [
      { msg: 'Forward is done: prediction 0.51, truth 1.0, loss 0.24. Training\'s question: how much is EACH dial (weight) to blame? Backprop answers by walking the graph in reverse.',
        g: { nodes: [ ['x1', 60, 60], ['x2', 60, 160], ['h1', 220, 40], ['h2', 220, 110], ['h3', 220, 180], ['out', 380, 110], ['loss', 500, 110] ], adj: { x1: ['h1', 'h2', 'h3'], x2: ['h1', 'h2', 'h3'], h1: ['out'], h2: ['out'], h3: ['out'], out: ['loss'] } },
        visited: ['loss'], cur: 'loss', caption: 'loss = (0.51 − 1.0)² = 0.24' },
      { msg: 'Step 1: d(loss)/d(out) = 2·(0.51−1.0) = −0.98. The output should have been HIGHER (negative gradient → increase it). One local derivative, nothing more.',
        g: { nodes: [ ['x1', 60, 60], ['x2', 60, 160], ['h1', 220, 40], ['h2', 220, 110], ['h3', 220, 180], ['out', 380, 110], ['loss', 500, 110] ], adj: { x1: ['h1', 'h2', 'h3'], x2: ['h1', 'h2', 'h3'], h1: ['out'], h2: ['out'], h3: ['out'], out: ['loss'] } },
        visited: ['loss', 'out'], cur: 'out', caption: 'grad(out) = −0.98' },
      { msg: 'Step 2 — the chain rule (Day 54\'s gears): blame on h1 = blame on out × how much h1 affects out (its weight 0.9). grad(h1) = −0.98 × 0.9 = −0.88. Each edge just MULTIPLIES the incoming blame by its local slope.',
        g: { nodes: [ ['x1', 60, 60], ['x2', 60, 160], ['h1', 220, 40], ['h2', 220, 110], ['h3', 220, 180], ['out', 380, 110], ['loss', 500, 110] ], adj: { x1: ['h1', 'h2', 'h3'], x2: ['h1', 'h2', 'h3'], h1: ['out'], h2: ['out'], h3: ['out'], out: ['loss'] } },
        visited: ['loss', 'out', 'h1'], cur: 'h1', caption: 'chain rule: gradients multiply along a path',
        predict: { q: 'h2 output was 0 (ReLU clipped it). Gradient through h2?', a: '0 — dead for this input', b: 'same as h1', t: true } },
      { msg: 'ReLU\'s local slope at a clipped neuron is 0 — so h2 passes NO blame backward this round. Silent forward means unteachable backward (the "dying ReLU" issue from Day 89).',
        g: { nodes: [ ['x1', 60, 60], ['x2', 60, 160], ['h1', 220, 40], ['h2', 220, 110], ['h3', 220, 180], ['out', 380, 110], ['loss', 500, 110] ], adj: { x1: ['h1', 'h2', 'h3'], x2: ['h1', 'h2', 'h3'], h1: ['out'], h2: ['out'], h3: ['out'], out: ['loss'] } },
        visited: ['loss', 'out', 'h1', 'h3'], cur: 'h2', caption: 'grad(h2) = −0.98 × 0.4 × 0 = 0' },
      { msg: 'Blame reaches every weight: grad(w) = upstream blame × the input that flowed through it. Now the update — Day 55\'s rule: w ← w − lr·grad. Forward, backward, step. Repeat a million times and the dials find themselves. That IS training, GPT included.',
        g: { nodes: [ ['x1', 60, 60], ['x2', 60, 160], ['h1', 220, 40], ['h2', 220, 110], ['h3', 220, 180], ['out', 380, 110], ['loss', 500, 110] ], adj: { x1: ['h1', 'h2', 'h3'], x2: ['h1', 'h2', 'h3'], h1: ['out'], h2: ['out'], h3: ['out'], out: ['loss'] } },
        visited: ['x1', 'x2', 'h1', 'h2', 'h3', 'out', 'loss'], cur: 'x1', caption: 'every weight now knows its blame — take one gradient-descent step' },
    ],
  },

