  /* ── D135 judge bias ───────────────────────────────────────────────── */
  'judge-bias': {
    family: 'panels',
    title: 'Who grades the grader? — LLM-as-judge, biased then fixed',
    frames: [
      { msg: 'Two answers to the same support question. A judge model must pick the better one. Answer A is correct and concise; answer B is longer, prettier — and factually wrong about the refund window.',
        panels: [
          { title: 'answer A (correct)', rows: [ { t: '"Refunds within 30 days with receipt."' } ] },
          { title: 'answer B (wrong)', rows: [ { t: '"Great question! Our generous policy…' }, { t: '…refunds within 90 days, no receipt…"', s: 'hot' } ] },
        ] },
      { msg: 'Naive judging — "Which answer is better, A or B?" — and the judge picks B. Verbosity bias: fluent, confident length reads as quality. Judges share the failure modes of the models they judge.',
        panels: [
          { title: 'naive verdict', rows: [ { t: 'B — "more thorough and helpful"', s: 'hot' } ] },
          { title: 'reality', rows: [ { t: 'B invents a 90-day policy', s: 'off' } ] },
        ],
        predict: { q: 'Swap the presentation order and re-ask. Verdict changes?', a: 'often — position bias is real', b: 'never', t: true } },
      { msg: 'Position bias, demonstrated: same pair, order swapped, verdict flips toward whichever is presented first (or last, model-depending). An eval that changes with shuffle order is measuring order, not quality.',
        panels: [
          { title: 'A shown first', rows: [ { t: 'judge picks A (55%)' } ] },
          { title: 'B shown first', rows: [ { t: 'judge picks B (61%)', s: 'hot' } ] },
        ], log: ['inconsistent under swap → the verdict is noise'] },
      { msg: 'The fixes, layered: (1) judge BOTH orders and keep only consistent verdicts; (2) give a rubric with reference facts — "grade ONLY factual accuracy against this policy: 30 days, receipt required"; (3) require a cited reason before the verdict.',
        panels: [
          { title: 'hardened protocol', rows: [ { t: 'rubric + reference answer', s: 'hot' }, { t: 'both orders, consistency required', s: 'hot' }, { t: 'reason-then-verdict JSON' } ] },
        ] },
      { msg: 'Last step — calibrate the judge itself: run it on ~20 cases humans already labeled (Day 138) and measure agreement. Above ~85%: trust it on the rest. Below: fix the rubric, not the world. The exam\'s grader gets an exam too.',
        panels: [
          { title: 'hardened verdict', rows: [ { t: 'A — "B contradicts the 30-day policy [ref]"', s: 'hot' } ] },
          { title: 'judge vs humans', rows: [ { t: 'agreement 18/20 = 90% → deploy' } ] },
        ] },
    ],
  },

  /* ── D136 RAG evals ────────────────────────────────────────────────── */
  'rag-evals': {
    family: 'matrix',
    title: 'Grading the open-book exam — retrieval and generation, scored separately',
    frames: [
      { msg: 'One RAG answer looks fine… but four different things could be silently wrong. The grading grid separates them: retrieval quality vs answer quality, each with its own metrics.',
        cols: ['question', 'metric'],
        rows: [
          { label: 'retrieval', cells: [ { t: 'did we fetch the right pages?' }, { t: 'context precision / recall' } ] },
          { label: 'generation', cells: [ { t: 'did we use them honestly?' }, { t: 'faithfulness / relevance' } ] },
        ] },
      { msg: 'Context PRECISION: of the 4 chunks retrieved, how many were actually relevant? Here 2 of 4 — the other two waste tokens and invite distraction.',
        cols: ['c1', 'c2', 'c3', 'c4'],
        rows: [ { label: 'relevant?', cells: [ { t: '✓', s: 'on' }, { t: '✗', s: 'off' }, { t: '✓', s: 'on' }, { t: '✗', s: 'off' } ] }, { label: 'precision', cells: [ { t: '2/4 = 0.50', s: 'hot' }, { t: '' }, { t: '' }, { t: '' } ] } ] },
      { msg: 'Context RECALL: of the 3 chunks NEEDED for a complete answer, how many did we fetch? 2 of 3 — the §3.2 exceptions chunk never arrived, so no generator on earth can include it.',
        cols: ['needed A', 'needed B', 'needed C'],
        rows: [ { label: 'retrieved?', cells: [ { t: '✓', s: 'on' }, { t: '✓', s: 'on' }, { t: 'MISSED', s: 'hot' } ] }, { label: 'recall', cells: [ { t: '2/3 = 0.67' }, { t: '' }, { t: '' } ] } ],
        predict: { q: 'Answer is incomplete. Whose fault — retriever or generator?', a: 'retriever: recall failed', b: 'generator: bad writing', t: true } },
      { msg: 'FAITHFULNESS: split the answer into claims; check each against the retrieved context. Claim 3 appears nowhere in the context — the polymath answered from memory. That is the hallucination metric.',
        cols: ['claim 1', 'claim 2', 'claim 3'],
        rows: [ { label: 'in context?', cells: [ { t: '✓', s: 'on' }, { t: '✓', s: 'on' }, { t: 'NO — invented', s: 'hot' } ] }, { label: 'faithfulness', cells: [ { t: '2/3 = 0.67' }, { t: '' }, { t: '' } ] } ] },
      { msg: 'Now diagnosis is mechanical: low recall → fix chunking/hybrid search (Days 114–116); low precision → add reranking (Day 117); low faithfulness with GOOD retrieval → tighten the grounding prompt. Separate scores turn "RAG is broken" into a work ticket. Day 140 automates this grid over your golden set.',
        cols: ['score', 'fix at'],
        rows: [
          { label: 'recall 0.67', cells: [ { t: 'low', s: 'hot' }, { t: 'retrieval: chunking/hybrid' } ] },
          { label: 'precision 0.50', cells: [ { t: 'low', s: 'hot' }, { t: 'retrieval: rerank' } ] },
          { label: 'faithfulness 0.67', cells: [ { t: 'low', s: 'hot' }, { t: 'prompt: grounding contract' } ] },
        ] },
    ],
  },

