        stages: [ { id: 'push', label: 'git push' }, { id: 'test', label: 'Tests', sub: 'pytest' }, { id: 'evalg', label: 'EVAL GATE', sub: 'golden set' }, { id: 'build', label: 'Build', sub: 'docker image' }, { id: 'stage', label: 'Staging' }, { id: 'prod', label: 'Production' } ],
        active: 'evalg', done: ['push', 'test'], payload: 'faithfulness 0.71 vs baseline 0.84 — REGRESSION',
