  /* ── D143 data flywheel ────────────────────────────────────────────── */
  'flywheel': {
    family: 'flow',
    title: 'Every flight teaches the fleet — the data flywheel, one revolution',
    frames: [
      { msg: 'Production serves thousands of requests. Each leaves a structured log: prompt, retrieved context, answer, latency — and, crucially, user feedback. The raw ore of improvement.',
        stages: [ { id: 'prod', label: 'Production', sub: 'logs + feedback' }, { id: 'mine', label: 'Mine failures', sub: 'cluster' }, { id: 'case', label: 'New golden cases' }, { id: 'fix', label: 'Fix', sub: 'prompt/retrieval' }, { id: 'gate', label: 'Gate', sub: 'CI evals' } ],
        active: 'prod', payload: 'today: 4,200 requests · 37 thumbs-down · 12 "wrong answer" reports' },
      { msg: 'Mine the failures: cluster the thumbs-downs and low-confidence traces. A pattern emerges — 9 of 12 wrong answers involve QUARTERLY DATE questions ("what changed in Q2?").',
        stages: [ { id: 'prod', label: 'Production', sub: 'logs + feedback' }, { id: 'mine', label: 'Mine failures', sub: 'cluster' }, { id: 'case', label: 'New golden cases' }, { id: 'fix', label: 'Fix', sub: 'prompt/retrieval' }, { id: 'gate', label: 'Gate', sub: 'CI evals' } ],
        active: 'mine', done: ['prod'], payload: 'failure cluster: date-scoped questions → retrieval ignores doc dates',
        predict: { q: 'First action for this cluster?', a: 'turn examples into golden cases', b: 'hotfix the prompt immediately', t: true } },
      { msg: 'BEFORE fixing anything, freeze the failures as golden cases with correct answers. Now the bug is measurable — and can never return silently. The exam grows one real question harder.',
        stages: [ { id: 'prod', label: 'Production', sub: 'logs + feedback' }, { id: 'mine', label: 'Mine failures', sub: 'cluster' }, { id: 'case', label: 'New golden cases' }, { id: 'fix', label: 'Fix', sub: 'prompt/retrieval' }, { id: 'gate', label: 'Gate', sub: 'CI evals' } ],
        active: 'case', done: ['prod', 'mine'], payload: '+8 cases: {"q": "What changed in Q2?", "must_use": "docs dated 2026-04..06"}' },
      { msg: 'Now fix with the failing cases as your target: add date metadata to chunks + a recency filter (Day 116\'s toolbox). The new cases go from 1/8 to 7/8 passing; the old set stays green.',
        stages: [ { id: 'prod', label: 'Production', sub: 'logs + feedback' }, { id: 'mine', label: 'Mine failures', sub: 'cluster' }, { id: 'case', label: 'New golden cases' }, { id: 'fix', label: 'Fix', sub: 'prompt/retrieval' }, { id: 'gate', label: 'Gate', sub: 'CI evals' } ],
        active: 'fix', done: ['prod', 'mine', 'case'], payload: 'date-filtered retrieval: new cases 7/8 · full suite still ≥ baseline' },
      { msg: 'The fix ships through the eval gate, production generates fresh logs, and the wheel turns again. Teams that spin this loop weekly compound; teams that skip it re-fight the same bugs forever. This is the moat: YOUR failures become YOUR eval set, which no competitor can copy.',
        stages: [ { id: 'prod', label: 'Production', sub: 'logs + feedback' }, { id: 'mine', label: 'Mine failures', sub: 'cluster' }, { id: 'case', label: 'New golden cases' }, { id: 'fix', label: 'Fix', sub: 'prompt/retrieval' }, { id: 'gate', label: 'Gate', sub: 'CI evals' } ],
        done: ['prod', 'mine', 'case', 'fix', 'gate'], payload: 'log → case → fix → gate → log … every revolution raises the floor' },
    ],
  },

