  /* ── D155 batching ─────────────────────────────────────────────────── */
  'batching-q': {
    family: 'hqueue',
    title: 'The drive-through window — why serving batches requests',
    frames: [
      { msg: 'Five requests arrive at your LLM service within 200 ms. The GPU can process them one at a time… or together. This choice defines your latency AND your cost.',
        items: ['req A', 'req B', 'req C', 'req D', 'req E'], hi: -1 },
      { msg: 'Sequential serving: A gets the GPU alone. A GPU doing one request at a time is mostly IDLE silicon — memory bandwidth is the bottleneck, not compute. E will wait through four full generations.',
        items: ['req A ⚙', 'req B', 'req C', 'req D', 'req E'], hi: 0,
        caption: 'GPU utilization ~15% · E\'s wait: 4 × full generation time',
        predict: { q: 'Batch all five together. Total throughput?', a: 'much higher — near 5×', b: 'same, GPUs are serial', t: true } },
      { msg: 'Static batching runs all five forward passes together — the matmuls just get a batch dimension (Day 51!). Throughput jumps ~4–5×. New problem: the batch finishes when the LONGEST answer finishes. Short answers wait for long ones.',
        items: ['batch: A+B+C+D+E ⚙'], hi: 0,
        caption: 'B finished at token 40 but sits idle while D writes token 900' },
      { msg: 'Continuous batching (vLLM-style) fixes it: generation is token-by-token, so at EVERY step the scheduler can slot a new request into a freed seat. B leaves at token 40; F takes its seat immediately.',
        items: ['A ⚙', 'F ⚙ (took B\'s seat)', 'C ⚙', 'D ⚙', 'E ⚙'], hi: 1,
        caption: 'seats refill mid-flight — utilization stays high, queues stay short' },
      { msg: 'The knobs you\'ll tune on Day 155: max batch size (throughput vs per-request latency), TTFT vs tokens/sec trade-offs, and KV-cache memory as the real seat limit. Cost per request falls almost linearly with utilization — batching IS the margin in LLM serving.',
        items: ['tune: batch size', 'watch: TTFT + p95', 'limit: KV-cache VRAM'], hi: -1 },
    ],
  },

